 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                # Diagonal corner rays get the neighboring corner's color,
                # with the four colors shifted clockwise around the block.
                corners = [
                    (r - 1, c - 1, -1, -1, grid[r + 2][c - 1]),  # NW <- SW
                    (r - 1, c + 2, -1, +1, grid[r - 1][c - 1]),  # NE <- NW
                    (r + 2, c - 1, +1, -1, grid[r + 2][c + 2]),  # SW <- SE
                    (r + 2, c + 2, +1, +1, grid[r - 1][c + 2]),  # SE <- NE
                ]
                for sr, sc, dr, dc, color in corners:
                    rr, cc = sr, sc
                    while 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
